{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/gen/l10n/app_localizations.dart';
import 'package:mad_flutter_practicum/domain/model/news_model.dart';
import 'package:mad_flutter_practicum/domain/repository/news_repository.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage>
    with SingleTickerProviderStateMixin {
  static const _scaleTween = Tween<double>(begin: 0.25, end: 1);

  List<NewsModel> _newsList = const [];
  bool _loading = true;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation =
      _scaleTween.animate(_scaleController);

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCacheThenNetwork();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _scaleTween.animate(_scaleController);
  }

  Future<void> _loadCacheThenNetwork() async {
    final newsRepository = context.read<NewsRepository>();

    // 1. Мгновенно показываем кэш из БД
    final cached = await newsRepository.loadNewsFeed(const NewsFeedFilter());
    if (!mounted) return;

    setState(() {
      _newsList = cached;
      _loading = false;
    });
    _scaleController.forward(); // анимация при показе кэша

    // 2. Параллельно в фоне запрашиваем сеть и обновляем список
    try {
      final fresh = await newsRepository.loadNewsFeed(
        const NewsFeedFilter(forceRefresh: true),
      );
      if (!mounted) return;
      setState(() {
        _newsList = fresh;
      });
    } catch (_) {
      // фоновая ошибка не критична — кэш уже показан
    }
  }

  @override
  Widget build(BuildContext context) {
    final loc = AppLocalizations.of(context);

    return Scaffold(
      appBar: AppBar(title: Text(loc.news)),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ScaleTransition(
              scale: _scaleAnimation,
              child: ListView.builder(
                itemCount: _newsList.length,
                itemBuilder: (BuildContext context, int index) {
                  final NewsModel news = _newsList[index];

                  return Padding(
                    key: ValueKey(news.link),
                    padding: index == 0
                        ? EdgeInsets.zero
                        : const EdgeInsets.only(top: 16),
                    child: NewsCard(model: news),
                  );
                },
                padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
              ),
            ),
    );
  }
}
","path":"lib/app/news_list/news_list_page.dart"}

